<?php
$page_title = 'Gestión de Capacidad TI';
require_once __DIR__.'/../../includes/load.php';
require_once __DIR__.'/../../config/app.php';
require_once __DIR__.'/bootstrap.php';
require_once __DIR__.'/importar_logs_lib.php';
require_once __DIR__.'/../incidencias/bootstrap.php';

inc_schema();
capacidad_ti_schema();
cap_log_schema();
require_permiso('capacidad_ti', 'ver');

function cap_json($value): string {
    return cap_h(json_encode($value, JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT));
}
function cap_badge(string $status): string {
    $status = strtoupper($status);
    $class = in_array($status,['ACTIVO','ACTIVA','NORMAL','ATENDIDA','BAJA'],true) ? 'success' : (in_array($status,['CRITICO','CRITICA','ALTA','ROJO','VENCIDO','RETIRADA'],true) ? 'danger' : 'warning');
    return '<span class="badge badge-'.$class.'">'.cap_h(str_replace('_',' ',$status)).'</span>';
}
function cap_unit(string $resource): string {
    $resource = strtoupper($resource);
    return $resource === 'CPU' ? 'MHz' : ($resource === 'RED' ? 'Mbps' : 'GB');
}

$machines = find_by_sql("SELECT IdMaquina,Host,Tipo_Activo,CategoriaEquipo,Mem_Ram,Tamano_Disco,Procesador,Ip,EstadoMaquina FROM maquina ORDER BY Host");
$hypervisors = find_by_sql("SELECT h.*,m.Host,m.Tipo_Activo,m.Mem_Ram,m.Tamano_Disco,m.Procesador FROM hipervisor h INNER JOIN maquina m ON m.IdMaquina=h.IdMaquina ORDER BY m.Host");
$vms = find_by_sql("SELECT v.*,m.Host,h.TipoHipervisor,h.NucleosCPU,h.FrecuenciaCPUMHz,
    (SELECT hc.PorcentajeUso FROM historial_capacidad hc WHERE hc.IdVM=v.IdVM ORDER BY hc.FechaEvaluacion DESC,hc.IdHistorial DESC LIMIT 1) UltimoUso,
    (SELECT hc.Estado FROM historial_capacidad hc WHERE hc.IdVM=v.IdVM ORDER BY hc.FechaEvaluacion DESC,hc.IdHistorial DESC LIMIT 1) UltimoEstado
    FROM maquina_virtual v INNER JOIN maquina m ON m.IdMaquina=v.IdMaquina LEFT JOIN hipervisor h ON h.IdHipervisor=v.IdHipervisor ORDER BY m.Host,v.NombreVM");
$vmTotalsByMachine = [];
foreach ($vms as $vm) {
    $machineId = (int)$vm['IdMaquina'];
    if (!isset($vmTotalsByMachine[$machineId])) {
        $vmTotalsByMachine[$machineId] = ['count' => 0, 'cpu' => 0.0, 'ram' => 0.0, 'disk' => 0.0];
    }
    $vmTotalsByMachine[$machineId]['count']++;
    $vmTotalsByMachine[$machineId]['cpu'] += (float)$vm['CPUAsignada'];
    $vmTotalsByMachine[$machineId]['ram'] += (float)$vm['RAMAsignada'];
    $vmTotalsByMachine[$machineId]['disk'] += (float)$vm['DiscoAsignado'];
}
$services = find_by_sql("SELECT s.*,(SELECT COUNT(*) FROM servicio_vm sv WHERE sv.IdServicio=s.IdServicio) TotalVM,(SELECT COUNT(*) FROM servicio_software ss WHERE ss.IdServicio=s.IdServicio) TotalSoftware,(SELECT COUNT(*) FROM servicio_aplicacion sa WHERE sa.IdServicio=s.IdServicio) TotalAplicaciones FROM servicio_ti s ORDER BY s.NombreServicio");
$applications = find_by_sql("SELECT a.*,
    (SELECT COUNT(*) FROM software_componente sc WHERE sc.IdAplicacion=a.IdAplicacion) TotalComponentes,
    (SELECT COUNT(*) FROM aplicacion_vm av WHERE av.IdAplicacion=a.IdAplicacion AND av.EstadoDespliegue='ACTIVO') TotalVM,
    (SELECT COUNT(*) FROM servicio_aplicacion sa WHERE sa.IdAplicacion=a.IdAplicacion) TotalServicios
    FROM aplicacion a ORDER BY a.NombreAplicacion");
$appComponents = find_by_sql("SELECT sc.* FROM software_componente sc ORDER BY sc.IdAplicacion,sc.TipoComponente,sc.NombreComponente");
$appVMs = find_by_sql("SELECT av.*,v.NombreVM,v.IP_VM,v.CPUAsignada,v.RAMAsignada,v.DiscoAsignado,v.EstadoVM,
    m.Host,m.Procesador,h.TipoHipervisor,h.FrecuenciaCPUMHz,
    (SELECT hc.ConsumoActual FROM historial_capacidad hc WHERE hc.IdVM=v.IdVM AND hc.Recurso='CPU' ORDER BY hc.FechaEvaluacion DESC,hc.IdHistorial DESC LIMIT 1) CPUConsumo,
    (SELECT hc.PorcentajeUso FROM historial_capacidad hc WHERE hc.IdVM=v.IdVM AND hc.Recurso='CPU' ORDER BY hc.FechaEvaluacion DESC,hc.IdHistorial DESC LIMIT 1) CPUUso,
    (SELECT hc.ConsumoActual FROM historial_capacidad hc WHERE hc.IdVM=v.IdVM AND hc.Recurso='RAM' ORDER BY hc.FechaEvaluacion DESC,hc.IdHistorial DESC LIMIT 1) RAMConsumo,
    (SELECT hc.PorcentajeUso FROM historial_capacidad hc WHERE hc.IdVM=v.IdVM AND hc.Recurso='RAM' ORDER BY hc.FechaEvaluacion DESC,hc.IdHistorial DESC LIMIT 1) RAMUso,
    (SELECT hc.ConsumoActual FROM historial_capacidad hc WHERE hc.IdVM=v.IdVM AND hc.Recurso='DISCO' ORDER BY hc.FechaEvaluacion DESC,hc.IdHistorial DESC LIMIT 1) DiscoConsumo,
    (SELECT hc.PorcentajeUso FROM historial_capacidad hc WHERE hc.IdVM=v.IdVM AND hc.Recurso='DISCO' ORDER BY hc.FechaEvaluacion DESC,hc.IdHistorial DESC LIMIT 1) DiscoUso,
    (SELECT MAX(hc.FechaEvaluacion) FROM historial_capacidad hc WHERE hc.IdVM=v.IdVM) UltimaMedicion
    FROM aplicacion_vm av INNER JOIN maquina_virtual v ON v.IdVM=av.IdVM
    INNER JOIN maquina m ON m.IdMaquina=v.IdMaquina LEFT JOIN hipervisor h ON h.IdHipervisor=v.IdHipervisor
    ORDER BY av.IdAplicacion,v.NombreVM");
$appServices = find_by_sql("SELECT sa.*,s.NombreServicio,s.Categoria,s.EstadoServicio FROM servicio_aplicacion sa INNER JOIN servicio_ti s ON s.IdServicio=sa.IdServicio ORDER BY sa.IdAplicacion,s.NombreServicio");
$serviceApplications = find_by_sql("SELECT sa.*,st.NombreServicio,a.NombreAplicacion,a.TipoAplicacion,
    GROUP_CONCAT(DISTINCT v.NombreVM ORDER BY v.NombreVM SEPARATOR ', ') VMs
    FROM servicio_aplicacion sa INNER JOIN servicio_ti st ON st.IdServicio=sa.IdServicio
    INNER JOIN aplicacion a ON a.IdAplicacion=sa.IdAplicacion
    LEFT JOIN aplicacion_vm av ON av.IdAplicacion=a.IdAplicacion AND av.EstadoDespliegue='ACTIVO'
    LEFT JOIN maquina_virtual v ON v.IdVM=av.IdVM
    GROUP BY sa.IdServicioAplicacion,sa.IdServicio,sa.IdAplicacion,sa.Modulo,sa.Observacion,st.NombreServicio,a.NombreAplicacion,a.TipoAplicacion
    ORDER BY st.NombreServicio,a.NombreAplicacion");
$appComponentsByApp=[]; $appVMsByApp=[]; $appServicesByApp=[];
foreach($appComponents as $row) $appComponentsByApp[(int)$row['IdAplicacion']][]=$row;
foreach($appVMs as $row) $appVMsByApp[(int)$row['IdAplicacion']][]=$row;
foreach($appServices as $row) $appServicesByApp[(int)$row['IdAplicacion']][]=$row;
$configs = find_by_sql("SELECT c.*,v.NombreVM,m.Host,h.FrecuenciaCPUMHz,(c.CPUAsignada*h.FrecuenciaCPUMHz) CapacidadCPUMHz FROM configuracion_capacidad_vm c INNER JOIN maquina_virtual v ON v.IdVM=c.IdVM INNER JOIN maquina m ON m.IdMaquina=v.IdMaquina LEFT JOIN hipervisor h ON h.IdHipervisor=v.IdHipervisor WHERE c.Activa=1 ORDER BY v.NombreVM");
$measurements = find_by_sql("SELECT hc.*,v.NombreVM,v.CPUAsignada,m.Host,h.FrecuenciaCPUMHz,
    CASE WHEN hc.RegistradoPor=0 AND hc.Observacion LIKE 'Importación automática%' THEN 'Importador automático' ELSE u.name END RegistradoPorNombre
    FROM historial_capacidad hc INNER JOIN maquina_virtual v ON v.IdVM=hc.IdVM INNER JOIN maquina m ON m.IdMaquina=v.IdMaquina
    LEFT JOIN hipervisor h ON h.IdHipervisor=v.IdHipervisor LEFT JOIN users u ON u.id=hc.RegistradoPor
    ORDER BY hc.FechaEvaluacion DESC,hc.IdHistorial DESC LIMIT 250");
$alerts = find_by_sql("SELECT a.*,v.NombreVM,v.IP_VM,m.Host,u.name AtendidaPorNombre,
    t.Folio,t.Titulo TituloIncidencia,t.Prioridad PrioridadIncidencia,t.Estado EstadoIncidencia
    FROM alerta_capacidad a
    INNER JOIN maquina_virtual v ON v.IdVM=a.IdVM
    INNER JOIN maquina m ON m.IdMaquina=v.IdMaquina
    LEFT JOIN users u ON u.id=a.AtendidaPor
    LEFT JOIN inc_tickets t ON t.IdTicket=a.IdIncidencia
    ORDER BY (a.EstadoAlerta='ABIERTA') DESC,a.FechaAlerta DESC LIMIT 250");
$logSources = find_by_sql("SELECT f.*,v.NombreVM,m.Host,
    (SELECT COUNT(*) FROM importacion_log_capacidad i WHERE i.IdVM=f.IdVM AND i.Estado='PROCESADO') TotalArchivos
    FROM fuente_log_capacidad f INNER JOIN maquina_virtual v ON v.IdVM=f.IdVM
    INNER JOIN maquina m ON m.IdMaquina=v.IdMaquina WHERE f.Activa=1 ORDER BY f.NombreFuente");
$logImports = find_by_sql("SELECT i.*,v.NombreVM FROM importacion_log_capacidad i INNER JOIN maquina_virtual v ON v.IdVM=i.IdVM ORDER BY i.FechaProceso DESC LIMIT 8");

$openAlerts = 0; $criticalAlerts = 0; $usageSum = 0; $usageCount = 0;
foreach ($alerts as $alert) if ($alert['EstadoAlerta']==='ABIERTA') { $openAlerts++; if ($alert['NivelAlerta']==='ROJO') $criticalAlerts++; }
foreach ($vms as $vm) if ($vm['UltimoUso'] !== null) { $usageSum += (float)$vm['UltimoUso']; $usageCount++; }
$averageUsage = $usageCount ? round($usageSum/$usageCount,1) : 0;
$criticalByVm = [];
foreach ($configs as $config) $criticalByVm[(int)$config['IdVM']] = (float)$config['UmbralCritico'];
$series = [];
foreach ($measurements as $measurement) $series[(int)$measurement['IdVM'].'|'.$measurement['Recurso']][] = $measurement;
$forecasts = [];
foreach ($series as $items) {
    if (count($items) < 2) continue;
    usort($items, fn($a,$b) => strcmp($a['FechaEvaluacion'],$b['FechaEvaluacion']));
    $first=$items[0]; $last=$items[count($items)-1];
    $days=max(0.01,(strtotime($last['FechaEvaluacion'])-strtotime($first['FechaEvaluacion']))/86400);
    $daily=((float)$last['PorcentajeUso']-(float)$first['PorcentajeUso'])/$days;
    $critical=$criticalByVm[(int)$last['IdVM']]??90; $projection='Tendencia estable'; $projectionDate='-';
    if ((float)$last['PorcentajeUso'] >= $critical) { $projection='Umbral alcanzado'; $projectionDate='Ahora'; }
    elseif ($daily > 0.01) { $remaining=($critical-(float)$last['PorcentajeUso'])/$daily; $projection='En crecimiento'; $projectionDate=date('d/m/Y',strtotime('+'.(int)ceil($remaining).' days',strtotime($last['FechaEvaluacion']))); }
    $forecasts[]=['vm'=>$last['NombreVM'],'resource'=>$last['Recurso'],'current'=>(float)$last['PorcentajeUso'],'monthly'=>round($daily*30,1),'critical'=>$critical,'status'=>$projection,'date'=>$projectionDate];
}
usort($forecasts, fn($a,$b) => ($a['date']==='Ahora'?-1:0)<=>($b['date']==='Ahora'?-1:0) ?: $b['monthly']<=>$a['monthly']);
$canCreate = tiene_permiso('capacidad_ti','crear'); $canEdit = tiene_permiso('capacidad_ti','editar'); $canDelete = tiene_permiso('capacidad_ti','eliminar');
$canViewIncidents = tiene_permiso('incidencias','ver');
$canCreateIncident = tiene_permiso('incidencias','crear');
$openIncidentTickets = ($canEdit && $canViewIncidents)
    ? find_by_sql("SELECT IdTicket,Folio,Titulo,Prioridad,Estado
        FROM inc_tickets
        WHERE Estado NOT IN ('RESUELTO','CERRADO','CANCELADO')
        ORDER BY FechaRegistro DESC,IdTicket DESC LIMIT 300")
    : [];
$currentUser = current_user();

include_once __DIR__.'/../../layouts/header.php';
?>
