  <section class="cap-vm-panel"><div class="cap-vm-panel-head"><div class="cap-vm-heading"><span class="cap-vm-heading-icon"><i class="fas fa-cubes"></i></span><div><h4 id="vmPanelTitle">Todas las máquinas virtuales</h4><small id="vmPanelSubtitle"><?=count($vms)?> máquinas virtuales en total</small></div></div><div class="cap-vm-tools"><div class="cap-vm-search"><i class="fas fa-search"></i><input id="vmSearch" type="search" placeholder="Buscar VM, IP o sistema..."></div><?php if($canCreate):?><button class="btn btn-info btn-sm" data-toggle="modal" data-target="#modalVM"><i class="fas fa-plus mr-1"></i>Nueva VM</button><?php endif;?></div></div><div id="vmHostContext" class="cap-vm-host-context"></div><div class="table-responsive"><table id="tblVM" class="table table-hover cap-table cap-vm-table mb-0"><thead><tr><th>Máquina virtual</th><th>Servidor / hipervisor</th><th>Sistema operativo</th><th>CPU</th><th>RAM</th><th>Disco</th><th>IP</th><th>Estado</th><th>Editar</th></tr></thead><tbody><?php foreach($vms as $vm):?><tr class="cap-vm-row" data-machine="<?=(int)$vm['IdMaquina']?>" data-search="<?=cap_h(strtolower($vm['NombreVM'].' '.$vm['Host'].' '.$vm['SistemaOperativo'].' '.$vm['IP_VM']))?>"><td><span class="cap-name"><?=cap_h($vm['NombreVM'])?></span><small class="d-block text-muted">VM #<?=(int)$vm['IdVM']?></small></td><td><strong><?=cap_h($vm['Host'])?></strong><small class="d-block text-muted"><?=cap_h($vm['TipoHipervisor']?:'Hipervisor no indicado')?></small></td><td><?=cap_h($vm['SistemaOperativo']?:'-')?></td><td><strong><?=cap_h($vm['CPUAsignada'])?></strong> vCPU</td><td><strong><?=cap_h($vm['RAMAsignada'])?></strong> GB</td><td><strong><?=cap_h($vm['DiscoAsignado'])?></strong> GB</td><td><?=cap_h($vm['IP_VM']?:'-')?></td><td><?=cap_badge($vm['EstadoVM'])?></td><td><?php if($canEdit):?><button class="btn btn-outline-info btn-sm btn-edit" data-modal="#modalVM" data-record="<?=cap_json($vm)?>" title="Editar <?=cap_h($vm['NombreVM'])?>"><i class="fas fa-edit"></i></button><?php else:?><span class="text-muted">-</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><div id="vmEmpty" class="cap-vm-empty"><i class="fas fa-cube"></i>No se encontraron máquinas virtuales para esta selección.</div></section>
 </div>
</div>

<div class="tab-pane fade" id="aplicaciones">
 <div class="card cap-panel mb-3"><div class="card-header"><div class="d-flex justify-content-between align-items-center flex-wrap"><div><h3 class="card-title mb-1"><i class="fas fa-shapes mr-2 text-info"></i>Catálogo de aplicaciones</h3><small class="d-block text-muted">Aplicaciones de negocio separadas de sus componentes técnicos e infraestructura.</small></div><div class="cap-app-toolbar"><div class="cap-app-filter cap-app-search"><label>Buscar</label><i class="fas fa-search"></i><input id="appSearch" class="form-control" placeholder="Aplicación, responsable..."></div><div class="cap-app-filter"><label>Estado</label><select id="appState" class="form-control"><option value="">Todos</option><option value="ACTIVA">Activas</option><option value="INACTIVA">Inactivas</option><option value="MANTENIMIENTO">Mantenimiento</option></select></div><div class="cap-app-filter"><label>Ambiente</label><select id="appEnvironment" class="form-control"><option value="">Todos</option><option value="PRODUCCION">Producción</option><option value="PRUEBAS">Pruebas</option><option value="DESARROLLO">Desarrollo</option><option value="CONTINGENCIA">Contingencia</option></select></div><?php if($canCreate):?><button class="btn btn-info btn-sm" data-toggle="modal" data-target="#modalApplication"><i class="fas fa-plus mr-1"></i>Nueva aplicación</button><?php endif;?></div></div></div><div class="card-body p-0"><div class="table-responsive"><table id="tblApplications" class="table table-hover cap-table mb-0 w-100"><thead><tr><th>Aplicación</th><th>Tipo</th><th>Versión</th><th>Ambiente</th><th>Responsable</th><th>Criticidad</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($applications as $index=>$app): $env=strtoupper($app['Ambiente']); $envClass=$env==='PRODUCCION'?'prod':($env==='PRUEBAS'?'test':($env==='DESARROLLO'?'dev':'contingency')); $stateClass=$app['EstadoAplicacion']==='ACTIVA'?'active':($app['EstadoAplicacion']==='MANTENIMIENTO'?'maintenance':'inactive');?><tr class="cap-app-row" data-app-id="<?=(int)$app['IdAplicacion']?>"><td><div class="cap-app-cell"><span class="cap-app-icon tone-<?=$index%4?>"><i class="fas fa-window-maximize"></i></span><div><span class="cap-name"><?=cap_h($app['NombreAplicacion'])?></span><small class="d-block text-muted"><?=(int)$app['TotalServicios']?> servicios · <?=(int)$app['TotalComponentes']?> componentes · <?=(int)$app['TotalVM']?> VM</small></div></div></td><td><?=cap_h($app['TipoAplicacion'])?></td><td><?=cap_h($app['Version']?:'-')?></td><td data-search="<?=cap_h($env)?>"><span class="cap-pill <?=$envClass?>"><?=cap_h(ucfirst(strtolower($env)))?></span></td><td><?=cap_h($app['Responsable']?:'-')?></td><td><?=cap_badge($app['Criticidad'])?></td><td data-search="<?=cap_h($app['EstadoAplicacion'])?>"><span class="cap-pill <?=$stateClass?>"><?=cap_h(ucfirst(strtolower($app['EstadoAplicacion'])))?></span></td><td><button type="button" class="btn btn-outline-info btn-sm btn-show-app" data-id="<?=(int)$app['IdAplicacion']?>" title="Ver ficha completa"><i class="fas fa-eye"></i></button><?php if($canEdit):?> <button type="button" class="btn btn-outline-info btn-sm btn-edit" data-modal="#modalApplication" data-record="<?=cap_json($app)?>" title="Editar aplicación"><i class="fas fa-edit"></i></button><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$applications):?><div class="cap-app-empty"><i class="fas fa-shapes fa-2x d-block mb-2"></i>No hay aplicaciones registradas. Use “Nueva aplicación” para comenzar.</div><?php endif;?></div></div>

 <?php foreach($applications as $appIndex=>$app): $appId=(int)$app['IdAplicacion']; $components=$appComponentsByApp[$appId]??[]; $appVmRows=$appVMsByApp[$appId]??[]; $appServiceRows=$appServicesByApp[$appId]??[]; $env=strtoupper($app['Ambiente']); $envClass=$env==='PRODUCCION'?'prod':($env==='PRUEBAS'?'test':($env==='DESARROLLO'?'dev':'contingency')); $stateClass=$app['EstadoAplicacion']==='ACTIVA'?'active':($app['EstadoAplicacion']==='MANTENIMIENTO'?'maintenance':'inactive'); ?>
 <div class="card cap-panel cap-app-detail <?=$appIndex===0?'is-active':''?>" id="appDetail<?=$appId?>"><div class="card-header"><div class="cap-detail-head"><div><small class="text-uppercase text-muted font-weight-bold">Ficha de aplicación</small><h3><?=cap_h($app['NombreAplicacion'])?></h3></div><div class="cap-detail-menu"><?php if($canCreate):?><button class="btn btn-outline-info btn-sm btn-app-action" data-modal="#modalComponent" data-app="<?=$appId?>"><i class="fas fa-layer-group mr-1"></i>Componente</button><button class="btn btn-outline-info btn-sm btn-app-action" data-modal="#modalApplicationVM" data-app="<?=$appId?>"><i class="fas fa-server mr-1"></i>Vincular VM</button><button class="btn btn-outline-info btn-sm btn-app-action" data-modal="#modalServiceApplication" data-app="<?=$appId?>"><i class="fas fa-hand-holding-heart mr-1"></i>Vincular servicio</button><?php endif;?><?php if($canEdit):?><button class="btn btn-info btn-sm btn-edit" data-modal="#modalApplication" data-record="<?=cap_json($app)?>"><i class="fas fa-edit mr-1"></i>Editar aplicación</button><?php endif;?></div></div><div class="cap-detail-tabs"><span><i class="fas fa-circle-info mr-1"></i>Información general</span><span><i class="fas fa-hand-holding-heart mr-1"></i>Servicios</span><span><i class="fas fa-layer-group mr-1"></i>Componentes</span><span><i class="fas fa-server mr-1"></i>Infraestructura</span><span><i class="fas fa-chart-line mr-1"></i>Capacidad</span></div></div><div class="card-body"><div class="cap-detail-layout"><div class="cap-detail-box"><h5>Información general</h5><dl class="cap-facts"><dt>Nombre</dt><dd><?=cap_h($app['NombreAplicacion'])?></dd><dt>Tipo</dt><dd><?=cap_h($app['TipoAplicacion'])?></dd><dt>Versión</dt><dd><?=cap_h($app['Version']?:'-')?></dd><dt>Fabricante</dt><dd><?=cap_h($app['Fabricante']?:'-')?></dd><dt>Ambiente</dt><dd><span class="cap-pill <?=$envClass?>"><?=cap_h(ucfirst(strtolower($env)))?></span></dd><dt>Estado</dt><dd><span class="cap-pill <?=$stateClass?>"><?=cap_h(ucfirst(strtolower($app['EstadoAplicacion'])))?></span></dd><dt>Criticidad</dt><dd><?=cap_badge($app['Criticidad'])?></dd><dt>Responsable</dt><dd><?=cap_h($app['Responsable']?:'Sin asignar')?></dd></dl><div class="cap-description"><strong class="d-block mb-1">Descripción</strong><?=nl2br(cap_h($app['Descripcion']?:'Sin descripción registrada.'))?></div></div><div class="cap-detail-grid"><div class="cap-detail-box"><h5><i class="fas fa-hand-holding-heart mr-1 text-success"></i>Servicios que soporta <span class="badge badge-light float-right"><?=count($appServiceRows)?></span></h5><?php if(!$appServiceRows):?><small class="text-muted">Todavía no hay servicios vinculados.</small><?php endif;?><ul class="cap-list-clean"><?php foreach($appServiceRows as $service):?><li><i class="fas fa-check"></i><div class="cap-list-main"><strong><?=cap_h($service['NombreServicio'])?></strong><small><?=cap_h($service['Modulo']?:$service['Categoria'])?></small></div></li><?php endforeach;?></ul><button type="button" class="btn btn-link btn-sm px-0 mt-1 btn-go-services">Ver catálogo de servicios <i class="fas fa-arrow-right ml-1"></i></button></div><div class="cap-detail-box"><h5><i class="fas fa-layer-group mr-1 text-info"></i>Componentes técnicos <span class="badge badge-light float-right"><?=count($components)?></span></h5><?php if(!$components):?><small class="text-muted">Agregue sistema operativo, plataforma, servidor web, runtime o base de datos.</small><?php endif;?><ul class="cap-list-clean"><?php foreach($components as $component):?><li><i class="fas fa-cube text-info mt-1"></i><div class="cap-list-main"><strong><?=cap_h($component['TipoComponente'])?>: <?=cap_h($component['NombreComponente'])?></strong><small><?=cap_h(trim($component['Version'].' '.$component['Fabricante']))?></small></div><?php if($canEdit):?><button type="button" class="btn btn-light btn-sm btn-edit-component" data-record="<?=cap_json($component)?>" title="Editar componente"><i class="fas fa-edit text-info"></i></button><?php endif;?></li><?php endforeach;?></ul></div><div class="cap-detail-box"><h5><i class="fas fa-server mr-1 text-info"></i>Infraestructura</h5><?php if(!$appVmRows):?><small class="text-muted">La aplicación aún no tiene una VM vinculada.</small><?php endif;?><?php foreach($appVmRows as $vm):?><div class="mb-3"><div class="cap-infra-row"><span><i class="fas fa-server"></i>Servidor</span><strong><?=cap_h($vm['Host'])?></strong></div><div class="cap-infra-row"><span><i class="fas fa-layer-group"></i>Hipervisor</span><strong><?=cap_h($vm['TipoHipervisor']?:'-')?></strong></div><div class="cap-infra-row"><span><i class="fas fa-cube"></i>VM</span><strong class="text-info"><?=cap_h($vm['NombreVM'])?></strong></div><div class="cap-infra-row"><span><i class="fas fa-network-wired"></i>IP</span><strong><?=cap_h($vm['IP_VM']?:'-')?></strong></div><div class="cap-infra-row"><span><i class="fas fa-tag"></i>Rol</span><strong><?=cap_h($vm['RolVM']?:'Servidor de aplicación')?></strong></div></div><?php endforeach;?></div><div class="cap-detail-box"><h5><i class="fas fa-chart-line mr-1 text-info"></i>Capacidad asociada por VM</h5><?php if(!$appVmRows):?><small class="text-muted">Vincule una VM para mostrar sus recursos y mediciones.</small><?php endif;?><?php foreach($appVmRows as $vm): $resources=[['CPU',$vm['CPUAsignada'].' vCPU',$vm['CPUConsumo'],'MHz',$vm['CPUUso']],['RAM',$vm['RAMAsignada'].' GB',$vm['RAMConsumo'],'GB',$vm['RAMUso']],['DISCO',$vm['DiscoAsignado'].' GB',$vm['DiscoConsumo'],'GB',$vm['DiscoUso']]];?><strong class="d-block mb-1"><?=cap_h($vm['NombreVM'])?></strong><table class="cap-capacity-table mb-2"><thead><tr><th>Recurso</th><th>Asignado</th><th>Uso actual</th><th>Uso %</th></tr></thead><tbody><?php foreach($resources as $resource): $usage=$resource[4]!==null?(float)$resource[4]:null;?><tr><td><?=$resource[0]?></td><td><?=cap_h($resource[1])?></td><td><?=$resource[2]!==null?number_format((float)$resource[2],2).' '.cap_h($resource[3]):'-'?></td><td><div class="d-flex align-items-center"><div class="cap-mini-progress mr-2"><span class="<?=$usage!==null&&$usage>=90?'danger':($usage!==null&&$usage>=75?'warn':'')?>" style="width:<?=min(100,max(0,$usage??0))?>%"></span></div><strong><?=$usage!==null?number_format($usage,1).'%':'-'?></strong></div></td></tr><?php endforeach;?></tbody></table><small class="text-muted d-block mb-2">Última medición: <?=$vm['UltimaMedicion']?date('d/m/Y H:i',strtotime($vm['UltimaMedicion'])):'Sin mediciones'?></small><?php endforeach;?><button type="button" class="btn btn-outline-info btn-sm btn-app-history"><i class="fas fa-clock-rotate-left mr-1"></i>Ver historial de mediciones</button></div></div></div></div></div>
 <?php endforeach;?>
</div>

