function cap_options(array $rows,string $value,string $label,string $extra=''): string { $html=''; foreach($rows as $row){$data=$extra!==''?' data-cap="'.cap_h($row[$extra]??'').'"':'';$html.='<option value="'.(int)$row[$value].'"'.$data.'>'.cap_h($row[$label]).'</option>';}return $html; }
$machineOptions=cap_options($machines,'IdMaquina','Host'); $hypervisorOptions=cap_options($hypervisors,'IdHipervisor','Host'); $vmOptions=cap_options($vms,'IdVM','NombreVM'); $serviceOptions=cap_options($services,'IdServicio','NombreServicio'); $applicationOptions=cap_options($applications,'IdAplicacion','NombreAplicacion');
?>
