<?php include_once __DIR__.'/../../layouts/footer.php'; ?>
<script>
$(function(){
  $('.cap-modal form').on('submit',function(event){
    var form=this;
    event.preventDefault();
    var submitButton=form.querySelector('.modal-footer button[type="submit"],.modal-footer button:not([type])');
    if(submitButton) submitButton.disabled=true;
    fetch('csrf.php',{credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json'}})
      .then(function(response){if(!response.ok)throw new Error('No se pudo renovar el token de seguridad.');return response.json()})
      .then(function(data){
        if(!data.success||!data.token)throw new Error('No se obtuvo un token de seguridad valido.');
        var input=form.querySelector('input[name="_csrf"]');
        if(!input){input=document.createElement('input');input.type='hidden';input.name='_csrf';form.appendChild(input)}
        input.value=data.token;
        HTMLFormElement.prototype.submit.call(form);
      })
      .catch(function(error){
        if(submitButton) submitButton.disabled=false;
        Swal.fire('No se pudo guardar',error.message||'Actualiza la pagina e intenta nuevamente.','error');
      });
  });
  function initSelect2(modal){ $(modal).find('.select2-cap').select2({theme:'bootstrap4',width:'100%',dropdownParent:$(modal),placeholder:'Buscar y seleccionar'}); }
  $('.cap-modal').on('shown.bs.modal',function(){initSelect2(this)}).on('hidden.bs.modal',function(){var form=this.querySelector('form');if(form){form.reset();$(form).find('input[name=id]').val(0);$(form).find('select').trigger('change.select2')}});
  $('.btn-edit').on('click',function(){
    var modal=$($(this).data('modal')),data=$(this).data('record'),form=modal.find('form')[0];
    if(typeof data==='string'){try{data=JSON.parse(data)}catch(e){App.toast('No se pudieron cargar los datos del registro.','error');return}}
    form.reset();
    Object.keys(data||{}).forEach(function(key){
      if(key==='id'||key==='action')return;
      var field=form.elements.namedItem(key);
      if(field&&data[key]!==null)$(field).val(data[key]).trigger('change');
    });
    var idKey=modal.is('#modalHypervisor')?'IdHipervisor':modal.is('#modalVM')?'IdVM':modal.is('#modalApplication')?'IdAplicacion':'IdServicio';
    $(form).find('input[name=id]').val(data[idKey]||0);
    modal.modal('show');
  });
  $('.btn-edit-config').on('click',function(){
    var modal=$('#modalConfig'),data=$(this).data('record'),form=modal.find('form')[0];
    if(typeof data==='string'){try{data=JSON.parse(data)}catch(e){App.toast('No se pudo cargar la configuración.','error');return}}
    form.reset();
    ['IdVM','Responsable','CPUAsignada','RAMAsignada','DiscoAsignado','UmbralAdvertencia','UmbralCritico','Observacion'].forEach(function(key){if(form.elements[key]&&data[key]!==null)$(form.elements[key]).val(data[key]).trigger('change')});
    form.elements.id.value=data.IdConfiguracion||0;
    modal.find('.modal-title').html('<i class="fas fa-edit mr-2"></i>Editar capacidad de '+(data.NombreVM||'VM'));
    modal.find('.modal-footer .btn-info').text('Guardar nueva versión');
    if($('#modalCurrentConfigs').hasClass('show')){
      $('#modalCurrentConfigs').one('hidden.bs.modal',function(){modal.modal('show')}).modal('hide');
    }else modal.modal('show');
  });
  $('#currentConfigSearch').on('input',function(){
    var term=$(this).val().toLowerCase().trim();
    $('#tblCurrentConfigs tbody tr').each(function(){$(this).toggle(!term||$(this).text().toLowerCase().indexOf(term)!==-1)});
  });
  $('#modalCurrentConfigs').on('hidden.bs.modal',function(){$('#currentConfigSearch').val('');$('#tblCurrentConfigs tbody tr').show()});
  $('#modalConfig').on('hidden.bs.modal',function(){$(this).find('.modal-title').html('<i class="fas fa-sliders mr-2"></i>Configuración de capacidad');$(this).find('.modal-footer .btn-info').text('Guardar configuración')});
  $('.btn-edit-component').on('click',function(){var data=$(this).data('record'),modal=$('#modalComponent'),form=modal.find('form')[0];if(typeof data==='string'){try{data=JSON.parse(data)}catch(e){App.toast('No se pudo cargar el componente.','error');return}}form.reset();['IdAplicacion','NombreComponente','TipoComponente','Version','Fabricante','EstadoComponente','Observacion'].forEach(function(key){if(form.elements[key]&&data[key]!==null)$(form.elements[key]).val(data[key]).trigger('change')});form.elements.id.value=data.IdComponente||0;modal.find('.modal-title').html('<i class="fas fa-edit mr-2"></i>Editar componente técnico');modal.find('.modal-footer .btn-info').html('<i class="fas fa-save mr-1"></i>Guardar cambios');modal.modal('show')});
  $('#modalComponent').on('hidden.bs.modal',function(){$(this).find('.modal-title').html('<i class="fas fa-layer-group mr-2"></i>Componente de la aplicación');$(this).find('.modal-footer .btn-info').html('<i class="fas fa-save mr-1"></i>Guardar componente')});
  $('.btn-app-action').on('click',function(){var modal=$($(this).data('modal')),app=$(this).data('app');var form=modal.find('form')[0];form.reset();$(form.elements.IdAplicacion).val(app).trigger('change');modal.modal('show')});
  function showApplication(id,scrollToDetail){$('.cap-app-detail').removeClass('is-active');$('#appDetail'+id).addClass('is-active');$('.cap-app-row').removeClass('is-selected');$('.cap-app-row[data-app-id="'+id+'"]').addClass('is-selected');if(scrollToDetail&&$('#appDetail'+id).length)$('html,body').animate({scrollTop:$('#appDetail'+id).offset().top-90},260)}
  $('.btn-show-app').on('click',function(event){event.stopPropagation();showApplication($(this).data('id'),true)});
  $('#tblApplications tbody').on('click','tr.cap-app-row',function(event){if($(event.target).closest('button,a').length)return;showApplication($(this).data('app-id'),true)});
  $('.btn-go-services').on('click',function(){$('#capTabs a[href="#servicios"]').tab('show');$('html,body').animate({scrollTop:$('#capTabs').offset().top-20},220)});
  $('.btn-app-history').on('click',function(){$('#capTabs a[href="#mediciones"]').tab('show');$('html,body').animate({scrollTop:$('#capTabs').offset().top-20},220)});
  $('.btn-link-alert-ticket').on('click',function(){
    var modal=$('#modalLinkAlertTicket');
    modal.find('input[name=IdAlerta]').val($(this).data('id'));
    modal.find('#linkAlertContext').text('Alerta de '+$(this).data('resource')+' en '+$(this).data('vm')+'. Seleccione el ticket que recibirá esta evidencia.');
    modal.modal('show');
  });
  $('.btn-close-alert').on('click',function(){$('#modalCloseAlert input[name=id]').val($(this).data('id'));$('#closeAlertVM').text($(this).data('vm'));$('#modalCloseAlert').modal('show')});
  function calcHostCapacity(){var cpus=parseFloat($('#hostCpuCount').val())||0,frequency=parseFloat($('#hostCpuFrequency').val())||0;$('#hostCpuTotal').val((cpus*frequency).toLocaleString('es-PE',{maximumFractionDigits:2})+' MHz')}
  $('#hostCpuCount,#hostCpuFrequency').on('input change',calcHostCapacity);$('#modalHypervisor').on('shown.bs.modal',calcHostCapacity);
  function calcMeasurement(){var total=parseFloat($('#measureTotal').val())||0,used=parseFloat($('#measureUsage').val())||0,p=total>0?(used/total*100):0;$('#measurePercent').val(p.toFixed(2)+'%').toggleClass('text-danger',p>=90).toggleClass('text-warning',p>=75&&p<90).toggleClass('text-success',p<75)}
  function prepareMeasurement(){var option=$('#measureVM option:selected'),resource=$('#measureResource').val(),vcpu=parseFloat(option.data('cpu'))||0,frequency=parseFloat(option.data('frequency'))||0,total='',unit='',message='<strong>Seleccione una VM y un recurso.</strong> El sistema cargará la capacidad configurada.';if(resource==='CPU'){total=vcpu*frequency;unit='MHz';message=frequency>0?'<strong>CPU:</strong> '+vcpu+' vCPU × '+frequency.toLocaleString('es-PE')+' MHz = '+total.toLocaleString('es-PE')+' MHz de capacidad. Uso = consumo VMware ÷ capacidad.':'<strong>Configuración incompleta:</strong> falta registrar la frecuencia MHz del servidor físico.'}if(resource==='RAM'){total=parseFloat(option.data('ram'))||0;unit='GB';message='<strong>RAM:</strong> uso = GB consumidos ÷ '+total.toLocaleString('es-PE')+' GB asignados.'}if(resource==='DISCO'){total=parseFloat(option.data('disk'))||0;unit='GB';message='<strong>Disco:</strong> uso = GB utilizados ÷ '+total.toLocaleString('es-PE')+' GB asignados.'}if(resource==='RED'){unit='Mbps';message='<strong>Red:</strong> indique primero la capacidad contratada o configurada en Mbps y luego el consumo actual.'}$('#measureTotal').prop('readonly',resource!=='RED').val(total||'');$('#measureUnit').text(resource?('Capacidad expresada en '+unit):'Seleccione un recurso');$('#measureUsageUnit').text(unit||'-');$('#measureUsageLabel').text(resource?('Consumo actual ('+unit+') *'):'Consumo actual *');$('#measureExplanation').html(message);calcMeasurement()}
  $('#measureVM,#measureResource').on('change',prepareMeasurement);$('#measureTotal,#measureUsage').on('input',calcMeasurement);
  var selectedMachine='all';
  function filterVirtualMachines(){
    var query=$.trim($('#vmSearch').val()||'').toLowerCase(),visible=0;
    $('.cap-vm-row').each(function(){
      var row=$(this),matchesHost=selectedMachine==='all'||String(row.data('machine'))===selectedMachine,matchesText=!query||String(row.data('search')||'').indexOf(query)!==-1;
      row.toggle(matchesHost&&matchesText);
      if(matchesHost&&matchesText)visible++;
    });
    $('#vmEmpty').toggle(visible===0);
    $('#tblVM').toggle(visible>0);
    $('#vmPanelSubtitle').text(visible+' máquina'+(visible===1?' virtual':'s virtuales')+(query?' que coinciden con la búsqueda':''));
  }
  $('.cap-host-card').on('click',function(){
    var card=$(this),host=card.data('host'),platform=card.data('platform');
    selectedMachine=String(card.data('machine'));
    $('.cap-host-card').removeClass('is-selected');card.addClass('is-selected');
    $('#vmPanelTitle').text(selectedMachine==='all'?'Todas las máquinas virtuales':'VM alojadas en '+host);
    $('#vmHostContext').toggleClass('is-visible',selectedMachine!=='all').html(selectedMachine==='all'?'':'<i class="fas fa-link mr-1 text-info"></i> Relación activa: <strong>'+host+'</strong> <span class="mx-1">→</span> '+platform);
    filterVirtualMachines();
  });
  $('.cap-host-card[role="button"]').on('keydown',function(event){if(event.key==='Enter'||event.key===' '){event.preventDefault();$(this).trigger('click')}});
  $('#vmSearch').on('input',filterVirtualMachines);
  var hash=location.hash;if(hash&&$(hash).hasClass('tab-pane')){$('#capTabs a[href="'+hash+'"]').tab('show')}$('#capTabs a').on('shown.bs.tab',function(e){history.replaceState(null,'',e.target.hash)});
  if($('#tblApplications').length){var appTable=$('#tblApplications').DataTable({responsive:true,pageLength:10,order:[],dom:'rt<"d-flex justify-content-between align-items-center flex-wrap p-3"ip>',language:DATATABLES_SPANISH,autoWidth:false});$('#appSearch').on('input',function(){appTable.search(this.value).draw()});$('#appState').on('change',function(){appTable.column(6).search(this.value?'^'+this.value+'$':'',true,false).draw()});$('#appEnvironment').on('change',function(){appTable.column(3).search(this.value?'^'+this.value+'$':'',true,false).draw()});var firstApp=$('.cap-app-row').first().data('app-id');if(firstApp)showApplication(firstApp,false)}
  ['#tblMeasurements','#tblAlerts'].forEach(function(id){if($(id).length)$(id).DataTable({responsive:true,pageLength:10,order:[],language:DATATABLES_SPANISH,autoWidth:false})});
});
</script>
